select * from dws_za_outbound_call_statistics
where is_delete = 0

    and report_date like concat("%", #{month},"%")


    and user_type in

        #{userType}


order by report_date desc;

select * from dws_report_statistic_transfer_detail
where report_id = #{reportId} and score_field = #{field}

     and dimension_field = #{dimensionField}


     and dimension_value = #{dimensionValue}


     and item_name = #{itemName}

order by score_value desc;

select * from dws_report_statistic_transfer_detail
where report_id = #{reportId}

     and score_field = #{scoreField}


     and dimension_field = #{dimensionField}


     and dimension_value = #{dimensionValue}


     and item_name = #{itemName}

order by score_value desc

select * from dws_report_statistic_field
where report_id = #{reportId}

    and field_y in

        #{fieldY}



     and item_name = #{itemName}


    ${orderFragment}
